// Focused synthetic checks: real signatures/encryption, memory persistence and
// Engine presentation merge. No model, relay, network, grants or execution.
import assert from 'node:assert/strict';
import * as wire from '../static/wire.mjs';
import {Engine,memoryStore} from '../static/engine.mjs';
const keys=await wire.newKeys(), peerKeys=await wire.newKeys();
const sender=await wire.publicEntry(keys,'alice/desk'),peer=await wire.publicEntry(peerKeys,'bob/desk');
const fp=await wire.fingerprint(sender),peerFP=await wire.fingerprint(peer);
const root=await wire.newRoot(keys,{person:'1'.repeat(32),roster:'1'.repeat(64),address:sender.address,fingerprint:fp},{person:'2'.repeat(32),roster:'2'.repeat(64)});
const conv=await wire.rootID(root), group='a'.repeat(32),lid='b'.repeat(32);
const n={v:2,id:lid,lid,from:sender.address,to:peer.address,ts:1,conv,root:wire.rootJSON(root),kind:'question',body:'One human turn',origin:'ui',pid:'c'.repeat(32),target:{address:peer.address,fingerprint:peerFP},attachments:[],send_group:group};
const sealed=await wire.seal(n,keys,peer),opened=await wire.open(sealed,peerKeys,peer.address,sender);
assert.equal(opened.send_group,group);
assert.equal(await wire.groupHistoryContentHash(conv,n),await wire.groupHistoryContentHash(conv,{...n,send_group:'d'.repeat(32)}),'presentation must not change content identity');
for(const bad of [{send_group:'bad'}, {kind:'message'}, {origin:'agent:codex'}, {sub:'event'}, {target:null}, {pid:''}, {v:1}])await assert.rejects(wire.seal({...n,...bad},keys,peer),/send group/);
const item={...n,v:1,from_key:fp,at:1000};delete item.root;
assert.equal(wire.parseHistory(wire.historyJSON(item)).send_group,group);
assert(!wire.historyJSON({...item,send_group:undefined}).includes('send_group'));
const store=memoryStore(), e=new Engine({store,base:'http://127.0.0.1:1',fetch:()=>{throw Error('no network')}});
const row={...n,fp,at:1000,dir:'in',state:''};
await store.write([{s:'inbox',k:n.id,v:row},{s:'lids',k:fp+'/'+lid,v:{id:n.id,conv,hash:'hash'}}]);
const merge=async message=>{const ops=await e.mergeSendGroupOps([],message,fp);await store.write(ops,ops.checks);};
await merge(n);await merge({...n,send_group:''});
assert.equal((await store.get('inbox',n.id)).send_group,group,'old stripped copy cannot erase known group');
const restarted=new Engine({store,base:'http://127.0.0.1:1',fetch:()=>{throw Error('no network')}});
assert.equal(restarted.itemOf(await store.get('inbox',n.id),false).send_group,group,'history after reload retains canonical group');
await merge({...n,send_group:'d'.repeat(32)});await merge(n);
assert.equal((await store.get('inbox',n.id)).send_group,'');assert.equal((await store.get('inbox',n.id)).send_group_conflict,true);
assert.equal(restarted.itemOf(await store.get('inbox',n.id),false).send_group,'','conflict cannot resurrect via history');
const other={...item,id:'e'.repeat(32),lid:'e'.repeat(32)};
const ops=await e.mergeSendGroupOps([{s:'inbox',k:other.id,v:{...other,conv,fp,history:true}}],{sub:'history',conv,body:wire.historyJSON(other)},fp);
await store.write(ops,ops.checks);assert.equal((await store.get('inbox',other.id)).send_group,group,'own history carries group without changing its child ID');
const old={...item,id:'f'.repeat(32),lid:'f'.repeat(32),send_group:undefined};
const oldOps=await e.mergeSendGroupOps([],{sub:'history',conv,body:wire.historyJSON(old)},fp);assert.equal(oldOps.length,0);
const profileGate={profile:async()=>{throw Error('offline')},pubOf:async()=>peer};
assert.equal(await Engine.prototype.sendGroupCopy.call(profileGate,peer.address,{},group),'','unknown/offline capability omits only display metadata');
const session='1'.repeat(32);
const caps=await wire.newCaps(peerKeys,peer.address,session,[wire.CapEnv2,wire.CapPerson,wire.CapRoom]);
profileGate.profile=async()=>({live:true,sessions:[session],caps:[wire.capsJSON(caps)]});
assert.equal(await Engine.prototype.sendGroupCopy.call(profileGate,peer.address,{},group),'','rm1 never implies sg1');
const newCaps=await wire.newCaps(peerKeys,peer.address,session,[wire.CapEnv2,wire.CapPerson,wire.CapRoom,wire.CapSendGroup]);
const oldSession='2'.repeat(32),oldCaps=await wire.newCaps(peerKeys,peer.address,oldSession,[wire.CapEnv2,wire.CapPerson,wire.CapRoom]);
profileGate.profile=async()=>({live:true,sessions:[session,oldSession],caps:[wire.capsJSON(newCaps),wire.capsJSON(oldCaps)]});
assert.equal(await Engine.prototype.sendGroupCopy.call(profileGate,peer.address,{},group),'','mixed old/new sessions omit display metadata for compatibility');
profileGate.profile=async()=>({live:true,sessions:[session],caps:[wire.capsJSON(newCaps)]});
assert.equal(await Engine.prototype.sendGroupCopy.call(profileGate,peer.address,{},group),group);
console.log('PASS send group: signed roundtrip, strict shapes, content identity, legacy omission, sticky conflicts, reload/history and explicit capability');
